css:
.fx-ms{width:min(560px,100%);border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);padding:1.6em}
.fx-ms .st{display:flex;align-items:center;margin-bottom:1.6em}
.fx-ms .st li{list-style:none;display:flex;align-items:center;gap:.5em;font:600 .82em var(--font-body);opacity:.55;flex:1}
.fx-ms .st li:last-child{flex:none}
.fx-ms .st li::after{content:"";flex:1;height:2px;background:var(--border);margin:0 .6em}.fx-ms .st li:last-child::after{display:none}
.fx-ms .st i{width:1.9em;height:1.9em;border-radius:50%;display:grid;place-items:center;border:2px solid var(--border);font-style:normal;font-weight:700;flex:none;transition:all calc(.25s/var(--speed))}
.fx-ms .st li.on,.fx-ms .st li.done{opacity:1}
.fx-ms .st li.on i{border-color:var(--primary);color:var(--primary)}
.fx-ms .st li.done i{background:var(--primary);border-color:var(--primary);color:var(--on-primary)}
.fx-ms .st ul{display:contents}
.fx-ms ul.st{padding:0;margin:0 0 1.6em}
.fx-ms .pane{display:none}.fx-ms .pane.on{display:block;animation:fx-ms-r calc(.35s/var(--speed)) both}
.fx-ms .pane.back{animation-name:fx-ms-l}
@keyframes fx-ms-r{from{opacity:0;transform:translateX(24px)}}@keyframes fx-ms-l{from{opacity:0;transform:translateX(-24px)}}
.fx-ms h3{font-size:1.35em;margin-bottom:1em}.fx-ms h3:focus{outline:none}
.fx-ms .f{margin-bottom:1em}.fx-ms label,.fx-ms legend{display:block;font:600 .88em var(--font-body);margin-bottom:.35em;padding:0}
.fx-ms input[type=text],.fx-ms input[type=tel],.fx-ms input[type=email],.fx-ms textarea,.fx-ms select{width:100%;padding:.75em .9em;border:1px solid var(--border);border-radius:calc(var(--radius)*.6);background:var(--surface);color:var(--text);font:inherit}
.fx-ms input:focus-visible,.fx-ms textarea:focus-visible,.fx-ms select:focus-visible{outline:2px solid var(--primary);outline-offset:1px}
.fx-ms [aria-invalid=true]{border-color:var(--accent)!important}
.fx-ms .err{display:block;color:var(--accent);font-size:.82em;min-height:1.2em;margin-top:.25em}
.fx-ms fieldset{border:0;padding:0;margin:0 0 1em}.fx-ms .chips{display:flex;flex-wrap:wrap;gap:.5em}
.fx-ms .chips label{margin:0;position:relative}.fx-ms .chips input{position:absolute;opacity:0}
.fx-ms .chips span{display:inline-block;padding:.5em 1em;border:1px solid var(--border);border-radius:99px;cursor:pointer;font-weight:600;font-size:.9em}
.fx-ms .chips input:checked+span{background:var(--primary);border-color:var(--primary);color:var(--on-primary)}
.fx-ms .chips input:focus-visible+span{outline:2px solid var(--primary);outline-offset:2px}
.fx-ms dl{display:grid;grid-template-columns:auto 1fr;gap:.5em 1.2em;margin:0 0 1em;font-size:.95em}.fx-ms dt{opacity:.6}.fx-ms dd{margin:0;font-weight:600}
.fx-ms .nav{display:flex;justify-content:space-between;margin-top:1.4em}
.fx-ms .nav button{padding:.75em 1.5em;border-radius:99px;border:1px solid var(--primary);background:none;color:var(--primary);font:700 .92em var(--font-body);cursor:pointer}
.fx-ms .nav button.go{background:var(--primary);color:var(--on-primary)}
.fx-ms .nav button[hidden]{display:none}
.fx-ms .ok{text-align:center;padding:1.5em 0}.fx-ms .ok b{display:grid;place-items:center;width:3.4em;height:3.4em;margin:0 auto 1em;border-radius:50%;background:var(--accent);color:var(--on-accent);font-size:1.4em}
@media(prefers-reduced-motion:reduce){.fx-ms .pane.on{animation:none}.fx-ms .st i{transition:none}}

js:
(function(){var r=document.querySelector('.fx-ms'),P=r.querySelectorAll('.pane'),S=r.querySelectorAll('.st li'),bk=r.querySelector('.bk'),go=r.querySelector('.go'),n=0,N=3;
function err(el,m){var e=el.closest('.f,fieldset').querySelector('.err');e.textContent=m||'';if(el.tagName!=='FIELDSET')el.setAttribute('aria-invalid',!!m)}
function val(i){var ok=true,f=function(id){return r.querySelector(id)};
 if(i===0){var a=f('#fx-ms-n'),p=f('#fx-ms-p'),e=f('#fx-ms-e');
  if(a.value.trim().length<2){err(a,'Please enter your name.');ok=false}else err(a);
  if(!/^[+0-9 ()-]{8,}$/.test(p.value.trim())){err(p,'Enter a valid phone number.');ok=false}else err(p);
  if(e.value&&!/^\S+@\S+\.\S+$/.test(e.value)){err(e,'That email looks incomplete.');ok=false}else err(e)}
 if(i===1){var s=r.querySelector('[name=svc]:checked'),fs=r.querySelector('fieldset'),b=f('#fx-ms-b');
  if(!s){fs.querySelector('.err').textContent='Pick a service.';ok=false}else fs.querySelector('.err').textContent='';
  if(!b.value){err(b,'Choose a budget range.');ok=false}else err(b)}
 if(i===2){var c=f('#fx-ms-c');if(!c.checked){err(c,'Please tick to continue.');ok=false}else err(c)}
 if(!ok){var x=P[i].querySelector('[aria-invalid=true]');if(x)x.focus()}return ok}
function show(k,back){P[n].classList.remove('on');n=k;P[n].classList.toggle('back',!!back);P[n].classList.add('on');
 S.forEach(function(li,j){li.classList.toggle('on',j===n);li.classList.toggle('done',j<n);li.querySelector('i').textContent=j<n?'✓':j+1;if(j===n)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current')});
 bk.hidden=n===0||n===3;go.parentNode.style.display=n===3?'none':'flex';go.textContent=n===2?'Send enquiry':'Next';
 if(n===2){var g=function(s){return (r.querySelector(s)||{}).value||'—'};r.querySelector('#fx-ms-r').innerHTML='<dt>Name</dt><dd>'+esc(g('#fx-ms-n'))+'</dd><dt>Phone</dt><dd>'+esc(g('#fx-ms-p'))+'</dd><dt>Service</dt><dd>'+esc((r.querySelector('[name=svc]:checked')||{}).value||'—')+'</dd><dt>Budget</dt><dd>'+esc(g('#fx-ms-b'))+'</dd>'}
 var h=P[n].querySelector('h3');h.tabIndex=-1;h.focus({preventScroll:true})}
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
go.onclick=function(){if(!val(n))return;show(n+1)};bk.onclick=function(){show(n-1,true)};
r.addEventListener('submit',function(e){e.preventDefault()});
r.addEventListener('keydown',function(e){if(e.key==='Enter'&&e.target.tagName!=='TEXTAREA'&&e.target.tagName!=='BUTTON'){e.preventDefault();go.click()}});show(0)})();
